from openpyxl import load_workbook

for data_only in (False, True):
    wb = load_workbook("budget.xlsx", data_only=data_only)
    ws = wb["Budget"]
    print(f"--- data_only={data_only} ---")
    for row in range(1, ws.max_row + 1):
        vals = []
        for col in range(1, ws.max_column + 1):
            c = ws.cell(row=row, column=col)
            if c.value is not None:
                vals.append(f"{c.coordinate}={c.value!r}")
        if vals:
            print(" | ".join(vals))
    print()

import pandas as pd

df = pd.read_excel("budget.xlsx", sheet_name="Budget", header=None)

expenses = []
for _, row in df.iloc[9:23].iterrows():  # expense rows (sheet rows 11-22, 0-idx 10..21)
    cat, desc, amt = row.iloc[0], row.iloc[1], row.iloc[2]
    if pd.notna(amt):
        expenses.append((cat, desc, float(amt)))

total = sum(x[2] for x in expenses)
print("Line items:")
for cat, desc, amt in expenses:
    print(f"  {cat:<16} {desc:<16} {amt:>10,.2f}")
print(f"TOTAL EXPENSES: {total:,.2f}")

by_cat = {}
for cat, desc, amt in expenses:
    by_cat[cat] = by_cat.get(cat, 0) + amt
print("\nBy category:")
for cat, amt in by_cat.items():
    print(f"  {cat:<16} {amt:>10,.2f}")

